import sys
import argparse
import os
import glob
import re
from html.parser import HTMLParser
from urllib.parse import urljoin

class MarkdownConverter(HTMLParser):
    def __init__(self, domain='', strong_delimiter='**', strikethrough=False, table=False):
        super().__init__()
        self.domain = domain
        self.strong_delimiter = strong_delimiter
        self.strikethrough = strikethrough
        self.table = table
        self.output = []
        self.stack = []
        self.list_stack = []
        self.last_tag = None
        self.in_pre = False
        self.in_code = False
        self.table_data = []
        self.in_table = False
        self.current_row = []
        self.current_cell = ""
        self.in_header = False

    def handle_starttag(self, tag, attrs):
        attrs_dict = dict(attrs)
        self.stack.append(tag)

        if tag == 'h1': self.output.append('\n# ')
        elif tag == 'h2': self.output.append('\n## ')
        elif tag == 'h3': self.output.append('\n### ')
        elif tag == 'h4': self.output.append('\n#### ')
        elif tag == 'h5': self.output.append('\n##### ')
        elif tag == 'h6': self.output.append('\n###### ')
        elif tag in ['p', 'div']: 
            if self.output and not self.output[-1].endswith('\n\n'):
                if not self.output[-1].endswith('\n'):
                    self.output.append('\n\n')
                else:
                    self.output.append('\n')
        elif tag == 'strong' or tag == 'b': self.output.append(self.strong_delimiter)
        elif tag == 'em' or tag == 'i': self.output.append('*')
        elif tag == 'del' or tag == 'strike' or tag == 's':
            if self.strikethrough: self.output.append('~~')
        elif tag == 'a':
            self.output.append('[')
        elif tag == 'img':
            alt = attrs_dict.get('alt', '')
            src = attrs_dict.get('src', '')
            if self.domain and src:
                src = urljoin(self.domain, src)
            title = attrs_dict.get('title', '')
            title_part = f' "{title}"' if title else ''
            self.output.append(f'![{alt}]({src}{title_part})')
        elif tag == 'ul':
            if self.list_stack and self.list_stack[-1] == 'ul':
                 self.output.append('\n  ') # Simple nesting
            elif self.list_stack:
                 self.output.append('\n  ')
            else:
                 self.output.append('\n')
            self.list_stack.append('ul')
        elif tag == 'ol':
            self.output.append('\n')
            self.list_stack.append('ol')
        elif tag == 'li':
            if self.list_stack[-1] == 'ul':
                self.output.append('- ')
            else:
                self.output.append('1. ') # Simplified
        elif tag == 'blockquote':
            self.output.append('\n> ')
        elif tag == 'pre':
            self.in_pre = True
            self.output.append('\n```\n')
        elif tag == 'code':
            if not self.in_pre:
                self.output.append('`')
            self.in_code = True
        elif tag == 'br':
            self.output.append('  \n')
        elif tag == 'hr':
            self.output.append('\n* * *\n')
        elif tag == 'table' and self.table:
            self.in_table = True
            self.table_data = []
        elif tag == 'tr' and self.in_table:
            self.current_row = []
        elif (tag == 'th' or tag == 'td') and self.in_table:
            self.in_header = (tag == 'th')
            self.current_cell = ""

    def handle_endtag(self, tag):
        if tag == 'h1' or tag == 'h2' or tag == 'h3' or tag == 'h4' or tag == 'h5' or tag == 'h6':
            self.output.append('\n')
        elif tag in ['p', 'div']:
            self.output.append('\n')
        elif tag == 'strong' or tag == 'b':
            self.output.append(self.strong_delimiter)
        elif tag == 'em' or tag == 'i':
            self.output.append('*')
        elif tag == 'del' or tag == 'strike' or tag == 's':
            if self.strikethrough: self.output.append('~~')
        elif tag == 'a':
            # This is tricky because we need the href here. 
            # We'll need to store it when we see the start tag.
            pass # See handle_starttag and data
        elif tag == 'ul' or tag == 'ol':
            self.list_stack.pop()
            self.output.append('\n')
        elif tag == 'li':
            self.output.append('\n')
        elif tag == 'pre':
            self.in_pre = False
            self.output.append('```\n')
        elif tag == 'code':
            if not self.in_pre:
                self.output.append('`')
            self.in_code = False
        elif tag == 'table' and self.table:
            self.in_table = False
            # Render table
            if self.table_data:
                # Basic table rendering
                for i, row in enumerate(self.table_data):
                    self.output.append('| ' + ' | '.join(row) + ' |\n')
                    if i == 0: # Header separator
                        self.output.append('|' + '|'.join(['----------' for _ in row]) + '|\n')
        elif tag == 'tr' and self.in_table:
            self.table_data.append(self.current_row)
        elif (tag == 'th' or tag == 'td') and self.in_table:
            self.current_row.append(self.current_cell.strip())

    def handle_data(self, data):
        if self.in_table:
            self.current_cell += data
        else:
            # Smart escaping would go here
            self.output.append(data)

